public static void main(String[] args) {
    var sc = new Scanner(System.in);
    int n = sc.nextInt();
    int m = sc.nextInt();

    // Initialize adjacency list to track friendships
    List<Set<Integer>> friendships = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
        friendships.add(new HashSet<>());
    }

    // Read friendships
    for (int i = 0; i < m; i++) {
        int x = sc.nextInt();
        int y = sc.nextInt();
        friendships.get(x).add(y);
        friendships.get(y).add(x);
    }

    long operations = 0;

    // Iterate over each user Y
    for (int y = 1; y <= n; y++) {
        // Iterate over each pair of friends (X, Y) and (Y, Z)
        for (int x : friendships.get(y)) {
            for (int z : friendships.get(y)) {
                if (x != z && !friendships.get(x).contains(z)) {
                    operations++;
                }
            }
        }
    }

    // Each operation is counted twice, so divide by 2
    System.out.println(operations / 2);
}
